    form: "medium text", skill: "exam", title: "The Cat Who Saved a Station", titleJp: "ねこの えきいん", tip: "In a news-style text, note numbers and the words before and after: 以前 and 今では mark the change.",
    lines: [
      { s: "", jp: "{山|やま}の{中|なか}の{小|ちい}さな{駅|えき}に、{最近|さいきん}{多|おお}くの{観光客|かんこうきゃく}が{来|き}ている。", ro: "Yama no naka no chiisana eki ni, saikin ōku no kankōkyaku ga kite iru.", en: "Many tourists have recently been coming to a small station in the mountains." },
      { s: "", jp: "もくてきは{電車|でんしゃ}ではなく、モチという{一|いっ}ぴきの{猫|ねこ}である。", ro: "Mokuteki wa densha de wa naku, Mochi to iu ippiki no neko de aru.", en: "Their aim is not the trains but a single cat called Mochi." },
      { s: "", jp: "モチは5{年|ねん}{前|まえ}、{雨|あめ}の{日|ひ}に{駅|えき}に{迷|まよ}い{込|こ}んで{来|き}た。", ro: "Mochi wa 5-nen mae, ame no hi ni eki ni mayoikonde kita.", en: "Mochi wandered into the station on a rainy day five years ago." },
      { s: "", jp: "{駅員|えきいん}が{世話|せわ}を{始|はじ}め、やがて{小|ちい}さなぼうしをかぶってかいさつの{横|よこ}に{座|すわ}るようになった。", ro: "Ekiin ga sewa o hajime, yagate chiisana bōshi o kabutte kaisatsu no yoko ni suwaru yō ni natta.", en: "The staff began caring for him, and before long he took to sitting beside the ticket gate in a little hat." },
      { s: "", jp: "その{写真|しゃしん}がインターネットで{話題|わだい}になると、{遠|とお}くから{見|み}に{来|く}る{人|ひと}が{増|ふ}え{始|はじ}めた。", ro: "Sono shashin ga intānetto de wadai ni naru to, tōku kara mi ni kuru hito ga fuehajimeta.", en: "When his photo became a talking point on the internet, more people began coming from far away to see him." },
      { s: "", jp: "{以前|いぜん}は{一日|いちにち}に50{人|にん}ほどだった{利用者|りようしゃ}が、{今|いま}では{休日|きゅうじつ}に500{人|にん}をこえる。", ro: "Izen wa ichinichi ni 50-nin hodo datta riyōsha ga, ima de wa kyūjitsu ni 500-nin o koeru.", en: "Where there used to be about 50 users a day, the number now passes 500 on holidays." },
      { s: "", jp: "{駅前|えきまえ}にはカフェや{土産物屋|みやげものや}が{開店|かいてん}し、{町|まち}に{明|あか}るさが{戻|もど}ってきた。", ro: "Ekimae ni wa kafe ya miyagemonoya ga kaiten shi, machi ni akarusa ga modotte kita.", en: "A café and a souvenir shop have opened in front of the station, and brightness has returned to the town." },
      { s: "", jp: "{一時|いちじ}は{電車|でんしゃ}がなくなるという{話|はなし}もあったが、その{計画|けいかく}は{消|き}えた。", ro: "Ichiji wa densha ga nakunaru to iu hanashi mo atta ga, sono keikaku wa kieta.", en: "At one time there was talk of the trains being withdrawn, but that plan has disappeared." },
      { s: "", jp: "{今|いま}では{町|まち}の{人|ひと}たちも、モチのことを「{町|まち}の{社長|しゃちょう}」と{呼|よ}んで{笑|わら}っている。", ro: "Ima de wa machi no hito tachi mo, Mochi no koto o “machi no shachō” to yonde waratte iru.", en: "Now the townspeople laughingly call Mochi \"the town's company president\"." },
      { s: "", jp: "ただ、{困|こま}ったこともある。", ro: "Tada, komatta koto mo aru.", en: "However, there are also problems." },
      { s: "", jp: "{写真|しゃしん}をとろうとしてせんろに{入|はい}る{人|ひと}が{出|で}てきたのだ。", ro: "Shashin o torō to shite senro ni hairu hito ga dete kita no da.", en: "Some people have begun walking onto the tracks to take photos." },
      { s: "", jp: "{駅|えき}は「モチに{会|あ}いに{来|き}てくれるのはうれしいが、{安全|あんぜん}が{何|なに}より{大切|たいせつ}だ」と{話|はな}している。", ro: "Eki wa “Mochi ni ai ni kite kureru no wa ureshii ga, anzen ga nani yori taisetsu da” to hanashite iru.", en: "The station says, \"We are glad people come to see Mochi, but safety is more important than anything.\"" }
    ],
    questions: [
      { q: "Why do tourists visit the station?", qjp: "かんこうきゃくは どうして その えきに きますか。", answer: "To see a cat", options: ["To ride a famous train","To visit a mountain café","To see a cat","To take photos of the tracks"] },
      { q: "What has changed in the town?", qjp: "まちは どう かわりましたか。", answer: "New shops opened and the town grew livelier", options: ["A new station was built","The trains were stopped","New shops opened and the town grew livelier","Fewer people use the station"] },
      { q: "What problem does the station mention?", qjp: "えきは どんな ことに こまって いますか。", answer: "People entering the tracks for photos", options: ["Too little money to care for Mochi","People entering the tracks for photos","Mochi running away from tourists","Tourists staying too late at night"] }
    ]
